-- Central retailer directory registry for the HI FASHION marketplace.
-- These are directory records only; no record implies affiliate approval or live product stock.
create table if not exists public.retailer_registry (
  merchant_id text primary key,
  display_name text not null,
  canonical_domain text not null,
  official_store_url text not null,
  region text not null default '',
  description text not null default '',
  listing_status text not null default 'directory_only'
    check (listing_status in ('directory_only','application_pending','approved_partner','connected_catalogue','paused')),
  integration_type text not null default 'outbound_store_link',
  affiliate_network text,
  programme_id text,
  approval_status text not null default 'not_applied_or_not_verified',
  product_feed_status text not null default 'not_connected',
  last_verified_at timestamptz,
  notes text not null default '',
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists retailer_registry_domain_idx on public.retailer_registry(canonical_domain);
create index if not exists retailer_registry_region_idx on public.retailer_registry(region);
create index if not exists retailer_registry_status_idx on public.retailer_registry(listing_status,product_feed_status);

alter table public.retailer_registry enable row level security;
drop policy if exists "Public can view active retailer directory" on public.retailer_registry;
create policy "Public can view active retailer directory"
  on public.retailer_registry for select to anon, authenticated
  using (is_active = true);
grant select on public.retailer_registry to anon, authenticated;
grant all privileges on public.retailer_registry to service_role;

insert into public.retailer_registry (
  merchant_id,display_name,canonical_domain,official_store_url,region,description,
  listing_status,integration_type,affiliate_network,programme_id,approval_status,
  product_feed_status,last_verified_at,notes,is_active
)
select
  x.merchant_id,x.display_name,x.canonical_domain,x.official_store_url,
  coalesce(x.region,''),coalesce(x.description,''),coalesce(x.listing_status,'directory_only'),
  coalesce(x.integration_type,'outbound_store_link'),x.affiliate_network,x.programme_id,
  coalesce(x.approval_status,'not_applied_or_not_verified'),
  coalesce(x.product_feed_status,'not_connected'),x.last_verified_at,x.notes,true
